const money = (value = 0, currency = 'USD') =>
  new Intl.NumberFormat('en-US', { style: 'currency', currency, maximumFractionDigits: 0 }).format(value);
const compactMoney = (value = 0) => value >= 1000 ? `$${(value / 1000).toFixed(value >= 100000 ? 0 : 1)}k` : money(value);
const pct = (value = 0) => `${(value * 100).toFixed(value % 0.1 === 0 ? 0 : 1)}%`;
const shortDate = (value?: string) => value ? new Intl.DateTimeFormat('en-US', { month: 'short', day: 'numeric' }).format(new Date(value)) : '—';
const fullDate = (value?: string) => value ? new Intl.DateTimeFormat('en-US', { month: 'short', day: 'numeric', year: 'numeric', hour: 'numeric', minute: '2-digit' }).format(new Date(value)) : '—';

